# Middleware classes for testing - defined at module level to avoid issues
class EarlyExitMiddleware:
    def __init__(self, view_func):
        self.view_func = view_func

    def process_request(self, request):
        return "early_response"


class ProcessViewEarlyMiddleware:
    def __init__(self, view_func):
        self.view_func = view_func

    def process_view(self, request, view_func, args, kwargs):
        return "view_early_response"


class ExceptionHandlingMiddleware:
    def __init__(self, view_func):
        self.view_func = view_func

    def process_exception(self, request, exception):
        return "exception_handled"


class NoHandleMiddleware:
    def __init__(self, view_func):
        self.view_func = view_func

    def process_exception(self, request, exception):
        return None


class ResponseMiddleware:
    def __init__(self, view_func):
        self.view_func = view_func

    def process_response(self, request, response):
        return "processed_response"


class TemplateResponse:
    def render(self):
        return "rendered"

    def add_post_render_callback(self, callback):
        callback(self)


class TemplateMiddleware:
    def __init__(self, view_func):
        self.view_func = view_func

    def process_template_response(self, request, response):
        return "template_processed"


class DummyMiddleware:
    def __init__(self, view_func):
        self.view_func = view_func


class TestClassOnlyMethod(SimpleTestCase):
    """Tests for classonlymethod class."""

    def setUp(self):
        from django.utils.decorators import classonlymethod

        class TestClass:
            @classmethod
            def normal_classmethod(cls):
                return "normal"

            @classonlymethod
            def restricted_method(cls):
                return "restricted"

        self.TestClass = TestClass
        self.classonlymethod = classonlymethod

    def test_classonlymethod_accessible_on_class(self):
        """Test that classonlymethod is accessible on the class."""
        result = self.TestClass.restricted_method()
        self.assertEqual(result, "restricted")

    def test_classonlymethod_raises_on_instance_access(self):
        """Test that accessing classonlymethod on instance raises AttributeError."""
        instance = self.TestClass()
        with self.assertRaises(AttributeError) as context:
            instance.restricted_method()
        self.assertIn("This method is available only on the class", str(context.exception))

    def test_normal_classmethod_accessible_on_instance(self):
        """Test that normal classmethods work on instances."""
        instance = self.TestClass()
        result = instance.normal_classmethod()
        self.assertEqual(result, "normal")


def make_simple_decorator(name):
    """Helper to create a simple decorator for testing."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            wrapper.called_with = (args, kwargs)
            wrapper.decorator_name = name
            return func(*args, **kwargs)
        return wrapper
    return decorator


class TestMultiDecorate(SimpleTestCase):
    """Tests for _multi_decorate function."""

    def setUp(self):
        from django.utils.decorators import _multi_decorate
        self._multi_decorate = _multi_decorate

    def test_single_decorator(self):
        """Test decorating a method with a single decorator."""
        class TestClass:
            def my_method(self, x):
                return x * 2

        decorated = self._multi_decorate(make_simple_decorator("single"), TestClass.my_method)
        instance = TestClass()
        result = decorated(instance, 5)
        self.assertEqual(result, 10)

    def test_multiple_decorators_list(self):
        """Test decorating with multiple decorators in a list."""
        class TestClass:
            def my_method(self, x):
                return x + 1

        decorated = self._multi_decorate(
            [make_simple_decorator("first"), make_simple_decorator("second")],
            TestClass.my_method
        )
        instance = TestClass()
        result = decorated(instance, 5)
        self.assertEqual(result, 6)

    def test_preserves_method_name(self):
        """Test that the wrapper preserves the original method's name."""
        class TestClass:
            def my_method(self, x):
                return x

        decorated = self._multi_decorate(make_simple_decorator("test"), TestClass.my_method)
        self.assertEqual(decorated.__name__, "my_method")


class TestMethodDecorator(SimpleTestCase):
    """Tests for method_decorator function."""

    def setUp(self):
        from django.utils.decorators import method_decorator
        self.method_decorator = method_decorator

    def test_decorator_on_function(self):
        """Test applying method_decorator to a standalone function."""
        @self.method_decorator(make_simple_decorator("func"))
        def my_func(x):
            return x * 2

        result = my_func(5)
        self.assertEqual(result, 10)

    def test_decorator_on_class_method(self):
        """Test applying method_decorator to a class method."""
        class MyView:
            @self.method_decorator(make_simple_decorator("view"))
            def get(self, request):
                return "response"

        view = MyView()
        result = view.get(None)
        self.assertEqual(result, "response")

    def test_decorator_with_args_passed_through(self):
        """Test that arguments are passed through correctly."""
        class MyView:
            @self.method_decorator(make_simple_decorator("test"))
            def process(self, x, y=10):
                return x + y

        view = MyView()
        result = view.process(5, y=20)
        self.assertEqual(result, 25)

    def test_value_error_missing_name(self):
        """Test ValueError when name is not provided for class decoration."""
        class MyClass:
            pass

        with self.assertRaises(ValueError) as context:
            self.method_decorator(make_simple_decorator("test"))(MyClass)
        self.assertIn("The keyword argument `name` must be the name of a method", str(context.exception))

    def test_value_error_invalid_name(self):
        """Test ValueError when name doesn't exist in class."""
        class MyClass:
            def existing_method(self):
                pass

        with self.assertRaises(ValueError) as context:
            self.method_decorator(make_simple_decorator("test"), name="nonexistent")(MyClass)
        self.assertIn("The keyword argument `name` must be the name of a method", str(context.exception))

    def test_type_error_non_callable(self):
        """Test TypeError when decorating non-callable attribute."""
        class MyClass:
            non_callable_attr = "not a method"

        with self.assertRaises(TypeError) as context:
            self.method_decorator(make_simple_decorator("test"), name="non_callable_attr")(MyClass)
        self.assertIn("isn't a callable attribute", str(context.exception))

    def test_decorator_preserves_attributes(self):
        """Test that decorator preserves attributes like __name__."""
        class MyClass:
            def my_method(self):
                pass

        self.method_decorator(make_simple_decorator("test"), name="my_method")(MyClass)
        self.assertTrue(hasattr(MyClass.my_method, '__name__'))

    def test_multiple_decorators_as_list(self):
        """Test using method_decorator with multiple decorators."""
        class MyView:
            @self.method_decorator([make_simple_decorator("a"), make_simple_decorator("b")], name="get")
            def get(self, request):
                return "ok"

        view = MyView()
        result = view.get(None)
        self.assertEqual(result, "ok")


