class TestEdgeCases(SimpleTestCase):
    """Tests for edge cases and error conditions."""

    def setUp(self):
        from django.utils.decorators import method_decorator, _multi_decorate
        self.method_decorator = method_decorator
        self._multi_decorate = _multi_decorate

    def test_empty_decorator_list(self):
        """Test behavior with empty decorator list."""
        class TestClass:
            def my_method(self, x):
                return x

        # Empty list should still work
        decorated = self._multi_decorate([], TestClass.my_method)
        instance = TestClass()
        result = decorated(instance, 42)
        self.assertEqual(result, 42)

    def test_decorator_with_kwargs(self):
        """Test decorator handling kwargs properly."""
        class TestClass:
            def my_method(self, x, y=None):
                return x + (y or 0)

        decorated = self._multi_decorate(
            make_simple_decorator("test"),
            TestClass.my_method
        )
        instance = TestClass()
        result = decorated(instance, 10, y=20)
        self.assertEqual(result, 30)

    def test_method_decorator_with_keyword_name(self):
        """Test method_decorator with explicit name parameter."""
        class MyView:
            def get(self, request):
                return "get"

            def post(self, request):
                return "post"

        decorated_get = self.method_decorator(make_simple_decorator("get"), name="get")
        decorated_get(MyView)

        view = MyView()
        result = view.get(None)
        self.assertEqual(result, "get")

    def test_method_decorator_modifies_class_in_place(self):
        """Test that method_decorator modifies the class in place."""
        class MyView:
            def get(self, request):
                return "original"

        self.method_decorator(make_simple_decorator("test"), name="get")(MyView)
        view = MyView()
        result = view.get(None)
        self.assertEqual(result, "original")

    def test_decorator_chain_order(self):
        """Test that decorators are applied in correct order."""
        call_order = []

        def outer(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                call_order.append("outer_before")
                result = func(*args, **kwargs)
                call_order.append("outer_after")
                return result
            return wrapper

        def inner(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                call_order.append("inner_before")
                result = func(*args, **kwargs)
                call_order.append("inner_after")
                return result
            return wrapper

        class TestClass:
            def my_method(self):
                call_order.append("method")
                return "result"

        decorated = self._multi_decorate([outer, inner], TestClass.my_method)
        instance = TestClass()
        result = decorated(instance)
        self.assertEqual(result, "result")
        # Outer should wrap inner, so order is: outer_before, inner_before, method, inner_after, outer_after
        self.assertEqual(call_order, ["outer_before", "inner_before", "method", "inner_after", "outer_after"])

