from django.template.defaultfilters import join
from django.test import SimpleTestCase
from django.utils.safestring import mark_safe

from ..utils import setup


class JoinTests(SimpleTestCase):
    @setup({"join01": "{{ a|join:', ' }}"})
    def test_join01(self):
        output = self.engine.render_to_string(
            "join01", {"a": ["a&b", "x"]}
        )
        self.assertEqual(output, "a&amp;b, x")

    @setup({"join02": "{% autoescape off %}{{ a|join:', ' }}{% endautoescape %}"})
    def test_join02(self):
        output = self.engine.render_to_string(
            "join02", {"a": ["a&b", "x"]}
        )
        self.assertEqual(output, "a&b, x")

    @setup({"join03": "{{ a|join:'' }}"})
    def test_join03(self):
        output = self.engine.render_to_string("join03", {"a": ["a", "b", "c"]})
        self.assertEqual(output, "abc")

    @setup({"join04": "{{ a|join:'-' }}"})
    def test_join04(self):
        output = self.engine.render_to_string("join04", {"a": [1, 2, 3]})
        self.assertEqual(output, "1-2-3")

    @setup({"join05": "{{ a|join:', ' }}"})
    def test_join05(self):
        output = self.engine.render_to_string("join05", {"a": []})
        self.assertEqual(output, "")

    @setup({"join06": "{{ a|join:', ' }}"})
    def test_join06(self):
        output = self.engine.render_to_string(
            "join06", {"a": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&b, x")

    @setup({"join07": "{% autoescape off %}{{ a|join:', ' }}{% endautoescape %}"})
    def test_join07(self):
        output = self.engine.render_to_string(
            "join07", {"a": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&b, x")

    @setup({"join08": "{{ a|join:',' }}"})
    def test_join08(self):
        output = self.engine.render_to_string(
            "join08", {"a": ["test", "value"]}
        )
        self.assertEqual(output, "test,value")

    @setup({"join09": "{{ a|join:' | ' }}"})
    def test_join09(self):
        output = self.engine.render_to_string(
            "join09", {"a": ["first", "middle", "last"]}
        )
        self.assertEqual(output, "first | middle | last")

    @setup({"join10": "{{ a|join:'\\n' }}"})
    def test_join10(self):
        output = self.engine.render_to_string(
            "join10", {"a": ["line1", "line2", "line3"]}
        )
        # In templates, \n is rendered literally
        self.assertEqual(output, "line1\\nline2\\nline3")


class FunctionTests(SimpleTestCase):
    def test_basic_join(self):
        """Test basic string joining functionality."""
        result = join(["a", "b", "c"], ", ")
        self.assertEqual(result, "a, b, c")

    def test_empty_list(self):
        """Test joining an empty list returns empty string."""
        result = join([], ", ")
        self.assertEqual(result, "")

    def test_single_item(self):
        """Test joining a single item list."""
        result = join(["only"], ", ")
        self.assertEqual(result, "only")

    def test_numbers_as_strings(self):
        """Test joining numbers converted to strings."""
        result = join([1, 2, 3], "-")
        self.assertEqual(result, "1-2-3")

    def test_with_special_chars_escaping(self):
        """Test that special characters are escaped when autoescape is True."""
        result = join(["a & b", "x < y"], ", ", autoescape=True)
        self.assertIn("&amp;", result)
        self.assertIn("&lt;", result)

    def test_no_autoescape(self):
        """Test joining without autoescape preserves raw HTML."""
        result = join(["<script>", "</script>"], "", autoescape=False)
        self.assertEqual(result, "<script></script>")

    def test_safedata_input(self):
        """Test joining SafeData objects."""
        safe_val = mark_safe("safe content")
        result = join([safe_val, "normal"], ", ", autoescape=True)
        self.assertIn("safe content", result)

    def test_mixed_safe_and_unsafe(self):
        """Test joining mix of safe and unsafe values."""
        safe_val = mark_safe("safe")
        unsafe_val = "unsafe & dangerous"
        result = join([safe_val, unsafe_val], ", ", autoescape=True)
        # Safe value should remain unescaped, unsafe should be escaped
        self.assertIn("safe", result)
        self.assertIn("&amp;", result)

    def test_unicode_characters(self):
        """Test joining strings with unicode characters."""
        result = join(["héllo", "wörld", "日本語"], "-")
        self.assertEqual(result, "héllo-wörld-日本語")

    def test_long_list(self):
        """Test joining a long list of items."""
        items = [str(i) for i in range(100)]
        result = join(items, ", ")
        expected = ", ".join(items)
        self.assertEqual(result, expected)

    def test_none_values_in_list(self):
        """Test joining list containing None values (converted to strings)."""
        result = join([None, "text", None], "|")
        self.assertEqual(result, "None|text|None")

    def test_boolean_values(self):
        """Test joining boolean values."""
        result = join([True, False, True], " ")
        self.assertEqual(result, "True False True")

    def test_dict_values(self):
        """Test joining dict values (converted to strings)."""
        result = join([{"a": 1}, {"b": 2}], " | ")
        # Dicts are escaped for HTML safety
        self.assertIn("&#x27;a&#x27;", result)

    def test_zero_separator(self):
        """Test joining with zero as separator (edge case)."""
        result = join(["a", "b"], 0)
        self.assertEqual(result, "a0b")

    def test_negative_index_behavior(self):
        """Test that join doesn't use negative indexing like slice does."""
        result = join(["a", "b", "c"], "-")
        self.assertNotEqual(result, "c-b-a")

    def test_whitespace_separator(self):
        """Test joining with whitespace separator."""
        result = join(["word1", "word2", "word3"], " ")
        self.assertEqual(result, "word1 word2 word3")

    def test_newline_separator(self):
        """Test joining with newline separator."""
        result = join(["line1", "line2"], "\n")
        self.assertEqual(result, "line1\nline2")

    def test_tab_separator(self):
        """Test joining with tab separator."""
        result = join(["col1", "col2"], "\t")
        self.assertEqual(result, "col1\tcol2")

    def test_multiple_spaces_separator(self):
        """Test joining with multiple spaces separator."""
        result = join(["a", "b"], "  ")
        self.assertEqual(result, "a  b")

    def test_empty_string_separator(self):
        """Test joining with empty string separator."""
        result = join(["hello", "world"], "")
        self.assertEqual(result, "helloworld")

    def test_mark_safe_output(self):
        """Test that join returns mark_safe output."""
        from django.utils.safestring import SafeString
        result = join(["a", "b"], ", ")
        self.assertIsInstance(result, SafeString)

