        self.all_sites = all_sites

    def tearDown(self):
        from django.contrib.admin.sites import all_sites
        all_sites.clear()

    def test_check_dependencies_success(self):
        from django.contrib.admin.checks import check_dependencies

        errors = check_dependencies()
        self.assertEqual(errors, [])

    def test_check_dependencies_no_contenttypes(self):
        from django.contrib.admin.checks import check_dependencies

        with self.settings(INSTALLED_APPS=["django.contrib.admin"]):
            errors = check_dependencies()
            self.assertEqual(len(errors), 3)
            self.assertIn("admin.E401", [e.id for e in errors])
            self.assertIn("admin.E405", [e.id for e in errors])
            self.assertIn("admin.E406", [e.id for e in errors])

    def test_check_dependencies_no_templates(self):
        from django.contrib.admin.checks import check_dependencies

        with self.settings(TEMPLATES=[]):
            errors = check_dependencies()
            self.assertEqual(len(errors), 1)
            self.assertEqual(errors[0].id, "admin.E403")

    def test_check_dependencies_no_auth_processor(self):
        from django.contrib.admin.checks import check_dependencies

        with self.settings(
            TEMPLATES=[{
                "BACKEND": "django.template.backends.django.DjangoTemplates",
                "DIRS": [],
                "APP_DIRS": True,
                "OPTIONS": {"context_processors": []},
            }]
        ):
            errors = check_dependencies()
            error_ids = [e.id for e in errors]
            self.assertIn("admin.E402", error_ids)
            self.assertIn("admin.E404", error_ids)

