class QTests(SimpleTestCase):
    def setUp(self):
        from django.db.models.query_utils import Q
        self.Q = Q

    def test_q_init_empty(self):
        q = self.Q()
        self.assertEqual(len(q.children), 0)
        self.assertEqual(q.connector, 'AND')
        self.assertFalse(q.negated)

    def test_q_init_with_args(self):
        q = self.Q(('field1', 'value1'))
        self.assertEqual(len(q.children), 1)
        self.assertEqual(q.children[0], ('field1', 'value1'))

    def test_q_init_with_kwargs(self):
        q = self.Q(field1='value1', field2='value2')
        self.assertEqual(len(q.children), 2)
        children_dict = dict(q.children)
        self.assertEqual(children_dict['field1'], 'value1')
        self.assertEqual(children_dict['field2'], 'value2')

    def test_q_init_with_connector(self):
        q = self.Q('field1', _connector=self.Q.OR)
        self.assertEqual(q.connector, 'OR')

    def test_q_init_with_negated(self):
        q = self.Q('field1', _negated=True)
        self.assertTrue(q.negated)

    def test_q_or_operator(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        combined = q1 | q2
        self.assertEqual(combined.connector, 'OR')
        self.assertEqual(len(combined.children), 2)

    def test_q_and_operator(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        combined = q1 & q2
        self.assertEqual(combined.connector, 'AND')
        self.assertEqual(len(combined.children), 2)

    def test_q_invert_operator(self):
        q = self.Q(field1='value1')
        inverted = ~q
        self.assertTrue(inverted.negated)
        self.assertEqual(len(inverted.children), 1)

    def test_q_combine_with_non_q_raises_typeerror(self):
        q = self.Q(field1='value1')
        with self.assertRaises(TypeError):
            q | "not a q object"

    def test_q_combine_with_empty_other_returns_self(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q()
        combined = q1 | q2
        self.assertEqual(len(combined.children), 1)

    def test_q_deconstruct_single_child(self):
        q = self.Q(field1='value1')
        path, args, kwargs = q.deconstruct()
        self.assertIn('Q', path)
        self.assertEqual(kwargs, {'field1': 'value1'})

    def test_q_deconstruct_multiple_children(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        combined = q1 & q2
        path, args, kwargs = combined.deconstruct()
        self.assertIn('Q', path)
        self.assertEqual(len(args), 2)

    def test_q_deconstruct_custom_connector(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        combined = q1 | q2
        path, args, kwargs = combined.deconstruct()
        self.assertIn('_connector', kwargs)
        self.assertEqual(kwargs['_connector'], 'OR')

    def test_q_deconstruct_negated(self):
        q = self.Q(field1='value1', _negated=True)
        path, args, kwargs = q.deconstruct()
        self.assertIn('_negated', kwargs)
        self.assertTrue(kwargs['_negated'])


