class FilteredRelationTests(SimpleTestCase):
    def setUp(self):
        from django.db.models.query_utils import FilteredRelation, Q
        self.FilteredRelation = FilteredRelation
        self.Q = Q

    def test_filtered_relation_init(self):
        fr = self.FilteredRelation('relation_name')
        self.assertEqual(fr.relation_name, 'relation_name')
        self.assertIsNone(fr.alias)
        self.assertEqual(fr.path, [])

    def test_filtered_relation_init_empty_relation_name_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.FilteredRelation('')

    def test_filtered_relation_init_invalid_condition_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.FilteredRelation('relation', condition='not a Q')

    def test_filtered_relation_eq_same(self):
        fr1 = self.FilteredRelation('rel', condition=self.Q(field='val'))
        fr2 = self.FilteredRelation('rel', condition=self.Q(field='val'))
        self.assertEqual(fr1, fr2)

    def test_filtered_relation_eq_different_name(self):
        fr1 = self.FilteredRelation('rel1', condition=self.Q())
        fr2 = self.FilteredRelation('rel2', condition=self.Q())
        self.assertNotEqual(fr1, fr2)

    def test_filtered_relation_eq_different_alias(self):
        fr1 = self.FilteredRelation('rel')
        fr1.alias = 'a1'
        fr2 = self.FilteredRelation('rel')
        fr2.alias = 'a2'
        self.assertNotEqual(fr1, fr2)

    def test_filtered_relation_clone(self):
        fr = self.FilteredRelation('rel', condition=self.Q(field='val'))
        fr.alias = 'test_alias'
        fr.path = ['path1']
        cloned = fr.clone()
        self.assertEqual(cloned.relation_name, 'rel')
        self.assertEqual(cloned.alias, 'test_alias')
        self.assertEqual(cloned.path, ['path1'])

    def test_filtered_relation_resolve_expression_raises_notimplemented(self):
        fr = self.FilteredRelation('rel')
        with self.assertRaises(NotImplementedError):
            fr.resolve_expression()

