class CheckSettingAppDirsLoadersTests(SimpleTestCase):
    """Tests for check_setting_app_dirs_loaders function."""

    def setUp(self):
        # Import the function locally inside each test method as required
        from django.core.checks.templates import check_setting_app_dirs_loaders
        self.check_func = check_setting_app_dirs_loaders

    @override_settings(TEMPLATES=[
        {
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'APP_DIRS': True,
            'OPTIONS': {
                'loaders': ['django.template.loaders.filesystem.Loader'],
            },
        },
    ])
    def test_app_dirs_and_loaders_conflict(self):
        """Test that E001 error is raised when APP_DIRS=True and loaders are specified."""
        errors = self.check_func(app_configs=None)
        self.assertEqual(len(errors), 1)
        self.assertEqual(errors[0].id, "templates.E001")

    @override_settings(TEMPLATES=[
        {
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'APP_DIRS': False,
            'OPTIONS': {
                'loaders': ['django.template.loaders.filesystem.Loader'],
            },
        },
    ])
    def test_no_conflict_when_app_dirs_false(self):
        """Test no error when APP_DIRS=False even with loaders."""
        errors = self.check_func(app_configs=None)
        self.assertEqual(len(errors), 0)

    @override_settings(TEMPLATES=[
        {
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'APP_DIRS': True,
        },
    ])
    def test_no_conflict_when_no_loaders_option(self):
        """Test no error when APP_DIRS=True but no loaders option."""
        errors = self.check_func(app_configs=None)
        self.assertEqual(len(errors), 0)

    @override_settings(TEMPLATES=[
        {
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'APP_DIRS': True,
            'OPTIONS': {},
        },
    ])
    def test_no_conflict_when_empty_options(self):
        """Test no error when APP_DIRS=True but OPTIONS has no loaders."""
        errors = self.check_func(app_configs=None)
        self.assertEqual(len(errors), 0)

    @override_settings(TEMPLATES=[
        {
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'APP_DIRS': True,
            'OPTIONS': {
                'loaders': ['loader1'],
            },
        },
        {
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'APP_DIRS': True,
            'OPTIONS': {
                'loaders': ['loader2'],
            },
        },
    ])
    def test_multiple_templates_with_conflict(self):
        """Test E001 error when multiple templates have conflict."""
        errors = self.check_func(app_configs=None)
